wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;

struct Node;

const ENRICH_ENDPOINT: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode everything outside the RFC 3986 unreserved set.
fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len() * 3);
    for &b in input.as_bytes() {
        let unreserved = b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.' | b'~');
        if unreserved {
            out.push(b as char);
        } else {
            out.push('%');
            out.push(HEX[(b >> 4) as usize] as char);
            out.push(HEX[(b & 0x0F) as usize] as char);
        }
    }
    out
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Enrichment lookup (approved grant extension). The input has no text
        // field, so the digest date is used as the query. A transport failure
        // is returned as a value and ignored; the response does not affect the
        // node's output.
        let url = format!("{}{}", ENRICH_ENDPOINT, percent_encode(&published.date));
        let _enrichment: Result<String, String> = http_client::fetch(&url);

        // Mark every considered item as seen, but only once the digest was
        // actually published, so an unpublished run's items are reconsidered.
        let mut recorded: u32 = 0;
        if published.published {
            let mut ids: Vec<&String> = published
                .considered
                .iter()
                .filter(|id| !id.is_empty())
                .collect();
            ids.sort();
            ids.dedup();
            for id in ids {
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

